import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function TeacherActivities({ timetable, teachingSubject, userName }) {
  const [activeSubTab, setActiveSubTab] = useState('forum'); 

  // --- 💬 1. Class Chat Forum Stream ---
  const [messages, setMessages] = useState([
    { id: 1, sender: `${userName || 'Teacher'}`, text: 'Hello class, please resolve any questions regarding the active lesson modules here.', isMe: true },
    { id: 2, sender: 'Student Node', text: 'Thank you teacher, the active lesson resources are perfectly clear.', isMe: false }
  ]);
  const [typeText, setTypeText] = useState('');

  const handleSend = (e) => {
    e.preventDefault();
    if (!typeText.trim()) return;
    const newMsg = { id: Date.now(), sender: `${userName || 'Teacher'}`, text: typeText, isMe: true };
    setMessages([...messages, newMsg]);
    setTypeText('');
  };

  // --- 🧩 2. Direct Lesson Activities Creator (Linked to empty database table) ---
  const [activities, setActivities] = useState([]);
  const [selectedLesson, setSelectedLesson] = useState('Lesson 01');
  const [activityType, setActivityType] = useState('MCQ'); // MCQ, BLANK, TRUE_FALSE
  
  const [questionText, setQuestionText] = useState('');
  const [correctAnswer, setCorrectAnswer] = useState('');
  const [optA, setOptA] = useState('');
  const [optB, setOptB] = useState('');
  const [optC, setOptC] = useState('');
  const [optD, setOptD] = useState('');

  const currentSubject = teachingSubject || 'Mathematics';

  // Fetch all activities from the dynamic database table
  const fetchActivities = () => {
    axios.get('http://localhost:8082/api/lesson-activities')
      .then(res => {
        const data = Array.isArray(res.data) ? res.data : [];
        // Only display questions matching this teacher's subject stream
        const filtered = data.filter(act => 
          String(act.subject).toLowerCase() === currentSubject.toLowerCase()
        );
        setActivities(filtered);
      })
      .catch(err => console.error("Error loading activities from database:", err));
  };

  useEffect(() => {
    fetchActivities();
  }, [activeSubTab]);

  // Handle direct database insertion when teacher submits the form
  const handleSaveActivity = (e) => {
    e.preventDefault();
    
    const payload = {
      lesson_name: selectedLesson,
      question_type: activityType,
      question_text: questionText,
      option_a: activityType !== 'BLANK' ? optA : null,
      option_b: activityType !== 'BLANK' ? optB : null,
      option_c: activityType === 'MCQ' ? optC : null,
      option_d: activityType === 'MCQ' ? optD : null,
      correct_answer: correctAnswer.trim().toUpperCase(),
      subject: currentSubject,
      teacher_name: userName || 'Teacher'
    };

    axios.post('http://localhost:8082/api/lesson-activities', payload)
      .then(() => {
        alert("Success: Question successfully inserted into database table!");
        // Clear input form fields
        setQuestionText('');
        setCorrectAnswer('');
        setOptA(''); setOptB(''); setOptC(''); setOptD('');
        fetchActivities(); // Refresh list view
      })
      .catch(err => alert("Insertion Error: " + err.message));
  };

  // Handle removing the query instance from the database table
  const handleDeleteActivity = (id) => {
    if (window.confirm("Are you sure you want to permanently delete this question from the database?")) {
      axios.delete(`http://localhost:8082/api/lesson-activities/${id}`)
        .then(() => fetchActivities())
        .catch(err => console.error(err));
    }
  };

  // Filter list view strictly based on the dropdown selected lesson module
  const filteredActivitiesList = activities.filter(act => act.lesson_name === selectedLesson);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '20px', fontFamily: 'sans-serif' }}>
      
      {/* Premium Sub Navigation Dock */}
      <div style={styles.tabContainer}>
        <button onClick={() => setActiveSubTab('forum')} style={styles.tabButton(activeSubTab === 'forum', '#145c2e')}>💬 Class Chat Forum</button>
        <button onClick={() => setActiveSubTab('activities')} style={styles.tabButton(activeSubTab === 'activities', '#6b21a8')}>🧩 Lesson Activities Creator</button>
      </div>

      {/* SUB-TAB 1: FORUM BOARD */}
      {activeSubTab === 'forum' && (
        <div style={styles.workspaceCard}>
          <h3 style={styles.cardSectionTitle}>Active Stream Feed ({currentSubject})</h3>
          <div style={styles.chatScroller}>
            {messages.map(m => (
              <div key={m.id} style={{ alignSelf: m.isMe ? 'flex-start' : 'flex-end', backgroundColor: m.isMe ? '#e2e8f0' : '#dcfce7', padding: '12px 18px', borderRadius: '12px', maxWidth: '70%', fontSize: '13.5px', display: 'flex', flexDirection: 'column' }}>
                <strong style={{ fontSize: '11px', color: m.isMe ? '#475569' : '#15803d', marginBottom: '4px' }}>{m.sender}</strong>
                <span>{m.text}</span>
              </div>
            ))}
          </div>
          <form onSubmit={handleSend} style={{ display: 'flex', gap: '12px', marginTop: '20px' }}>
            <input type="text" placeholder="Type your forum message here..." value={typeText} onChange={e => setTypeText(e.target.value)} style={styles.chatInput} />
            <button type="submit" style={styles.broadcastBtn}>Send Message 🚀</button>
          </form>
        </div>
      )}

      {/* SUB-TAB 2: DIRECT CREATION WORKSPACE SYSTEM */}
      {activeSubTab === 'activities' && (
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1.2fr', gap: '25px', alignItems: 'start' }}>
          
          {/* LEFT SIDE: DIRECT INSERTION INPUT FORM */}
          <div style={styles.interactiveCard('#6b21a8')}>
            <h3 style={styles.formTitle}>Create Lesson Activity Question</h3>
            <form onSubmit={handleSaveActivity} style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
              
              <label style={styles.fieldLabel}>Target Lesson Module</label>
              <select value={selectedLesson} onChange={e => setSelectedLesson(e.target.value)} style={styles.premiumInput}>
                <option value="Lesson 01">Lesson 01 - Intro</option>
                <option value="Lesson 02">Lesson 02 - Core Framework</option>
                <option value="Lesson 03">Lesson 03 - Advanced Concepts</option>
              </select>

              <label style={styles.fieldLabel}>Question Structure Type</label>
              <select value={activityType} onChange={e => { setActivityType(e.target.value); setQuestionText(''); setCorrectAnswer(''); }} style={styles.premiumInput}>
                <option value="MCQ">Multiple Choice Question (MCQ)</option>
                <option value="BLANK">Fill in the Blanks (Short Answer)</option>
                <option value="TRUE_FALSE">True / False Statement</option>
              </select>

              <label style={styles.fieldLabel}>Question Content Text</label>
              <textarea placeholder={activityType === 'BLANK' ? "Use ______ to denote the blank space..." : "Type the core question text here..."} value={questionText} onChange={e => setQuestionText(e.target.value)} required style={styles.premiumTextArea} />

              {/* RENDER DYNAMIC FIELD OPTIONS BASED ON TYPE */}
              {activityType === 'MCQ' && (
                <div style={{ display: 'flex', flexDirection: 'column', gap: '6px', padding: '10px', backgroundColor: '#f8fafc', borderRadius: '8px', border: '1px solid #cbd5e1' }}>
                  <input type="text" placeholder="Option A" value={optA} onChange={e => setOptA(e.target.value)} required style={styles.premiumInput} />
                  <input type="text" placeholder="Option B" value={optB} onChange={e => setOptB(e.target.value)} required style={styles.premiumInput} />
                  <input type="text" placeholder="Option C" value={optC} onChange={e => setOptC(e.target.value)} required style={styles.premiumInput} />
                  <input type="text" placeholder="Option D" value={optD} onChange={e => setOptD(e.target.value)} required style={styles.premiumInput} />
                </div>
              )}

              {activityType === 'TRUE_FALSE' && (
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px', padding: '10px', backgroundColor: '#f8fafc', borderRadius: '8px', border: '1px solid #cbd5e1' }}>
                  <input type="text" value="Option A: TRUE" disabled style={styles.premiumInput} />
                  <input type="text" value="Option B: FALSE" disabled style={styles.premiumInput} />
                </div>
              )}

              <label style={styles.fieldLabel}>Correct Answer Evaluation Key</label>
              <input type="text" placeholder={activityType === 'MCQ' ? "e.g., A / B / C / D" : activityType === 'TRUE_FALSE' ? "TRUE or FALSE" : "Type targeted text answer..."} value={correctAnswer} onChange={e => setCorrectAnswer(e.target.value)} required style={styles.premiumInput} />

              <button type="submit" style={styles.actionSubmitBtn('#6b21a8')}>Insert into Database Table 💾</button>
            </form>
          </div>

          {/* RIGHT SIDE: LIVE DISPLAY MATRIX REGISTRY */}
          <div style={styles.interactiveCard('#475569')}>
            <h3 style={styles.formTitle}>Active Lesson Activities Repository</h3>
            <select value={selectedLesson} onChange={e => setSelectedLesson(e.target.value)} style={{ ...styles.premiumInput, marginBottom: '15px' }}>
              <option value="Lesson 01">View: Lesson 01 - Intro</option>
              <option value="Lesson 02">View: Lesson 02 - Core Framework</option>
              <option value="Lesson 03">View: Lesson 03 - Advanced Concepts</option>
            </select>

            <div style={styles.listScroller}>
              {filteredActivitiesList.map((act, idx) => (
                <div key={act.id || idx} style={styles.bankItemRow}>
                  <div style={{ flex: 1 }}>
                    <span style={styles.typeBadge(act.question_type)}>{act.question_type}</span>
                    <p style={styles.itemQuestionText}>{act.question_text}</p>
                    {act.question_type === 'MCQ' && (
                      <div style={styles.itemMcqGrid}>
                        <div>A) {act.option_a}</div><div>B) {act.option_b}</div>
                        <div>C) {act.option_c}</div><div>D) {act.option_d}</div>
                      </div>
                    )}
                    <span style={{ fontSize: '12px', color: '#16a34a', fontWeight: 'bold' }}>Correct Key: {act.correct_answer}</span>
                  </div>
                  <button type="button" onClick={() => handleDeleteActivity(act.id)} style={styles.unlinkBtn}>Delete</button>
                </div>
              ))}
              {filteredActivitiesList.length === 0 && <p style={styles.emptyText}>No active questions registered in the database for this module yet.</p>}
            </div>
          </div>

        </div>
      )}
    </div>
  );
}

const styles = {
  tabContainer: { display: 'flex', gap: '5px', backgroundColor: '#f1f5f9', padding: '6px', borderRadius: '12px', width: 'fit-content' },
  tabButton: (isActive, color) => ({ padding: '10px 22px', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', fontSize: '13px', backgroundColor: isActive ? color : 'transparent', color: isActive ? 'white' : '#64748b' }),
  workspaceCard: { backgroundColor: 'white', padding: '25px', borderRadius: '16px', border: '1px solid #e2e8f0', display: 'flex', flexDirection: 'column' },
  cardSectionTitle: { margin: 0, fontSize: '15px', fontWeight: 'bold' },
  chatScroller: { border: '1px solid #e2e8f0', borderRadius: '12px', height: '280px', backgroundColor: '#f8fafc', padding: '20px', overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: '15px', marginTop: '15px' },
  chatInput: { flex: 1, padding: '12px 16px', borderRadius: '8px', border: '1px solid #cbd5e1', fontSize: '13.5px', outline: 'none' },
  broadcastBtn: { backgroundColor: '#145c2e', color: 'white', border: 'none', padding: '0 25px', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer' },
  interactiveCard: (color) => ({ backgroundColor: 'white', padding: '22px', borderRadius: '15px', borderTop: `5px solid ${color}`, borderLeft: '1px solid #e2e8f0', borderRight: '1px solid #e2e8f0', borderBottom: '1px solid #e2e8f0', boxShadow: '0 4px 15px rgba(0,0,0,0.01)' }),
  formTitle: { margin: '0 0 12px 0', fontSize: '15px', fontWeight: 'bold' },
  fieldLabel: { display: 'block', fontSize: '11px', fontWeight: 'bold', color: '#475569', marginBottom: '3px' },
  premiumInput: { width: '100%', padding: '10px', borderRadius: '8px', border: '1px solid #cbd5e1', backgroundColor: '#f8fafc', fontSize: '13px', boxSizing: 'border-box', outline: 'none' },
  premiumTextArea: { width: '100%', padding: '10px', borderRadius: '8px', border: '1px solid #cbd5e1', backgroundColor: '#f8fafc', fontSize: '13px', boxSizing: 'border-box', height: '55px', resize: 'none', outline: 'none' },
  actionSubmitBtn: (color) => ({ color: 'white', backgroundColor: color, border: 'none', padding: '11px', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', width: '100%', marginTop: '5px' }),
  listScroller: { display: 'flex', flexDirection: 'column', gap: '12px', maxHeight: '420px', overflowY: 'auto' },
  bankItemRow: { display: 'flex', gap: '12px', padding: '14px', backgroundColor: '#f8fafc', borderRadius: '12px', border: '1px solid #e2e8f0', alignItems: 'center' },
  typeBadge: (type) => ({ fontSize: '9px', fontWeight: 'bold', padding: '2px 6px', borderRadius: '4px', backgroundColor: type === 'MCQ' ? '#dbeafe' : '#f3e8ff', color: type === 'MCQ' ? '#2563eb' : '#6b21a8' }),
  itemQuestionText: { margin: '6px 0', fontSize: '13.5px', fontWeight: '600' },
  itemMcqGrid: { display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '4px', fontSize: '12px', color: '#64748b', marginBottom: '4px' },
  unlinkBtn: { backgroundColor: '#fee2e2', color: '#b91c1c', border: 'none', padding: '6px 12px', borderRadius: '6px', fontWeight: 'bold', fontSize: '11px', cursor: 'pointer' },
  emptyText: { color: '#94a3b8', fontStyle: 'italic', fontSize: '12.5px', textAlign: 'center', padding: '20px' }
};
